import 'dotenv/config';
import path from 'path';
import { promisify } from 'util';

import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { grpcServer } from '../../../src/services/grpc';

const PROTO_PATH = path.join(__dirname, '../../../proto/ethereum.proto');

const packageDefinition = protoLoader.loadSync(PROTO_PATH, {
  longs: String,
  defaults: false,
  oneofs: true,
});
const Ethereum = (grpc.loadPackageDefinition(packageDefinition) as any)?.ethereum.Ethereum;
let client;

describe('Ethereum service', () => {
  describe('GRPC service', () => {
    beforeAll(async () => {
      await grpcServer.start();
      client = new Ethereum(`localhost:${process.env.GRPC_PORT}`, grpc.credentials.createInsecure());
    });

    afterAll(async () => {
      client?.close();
      await grpcServer.stop();
    });

    describe('DeployAccount', () => {
      test('generate address from public key', async () => {
        const address = '0x370BA1dc25C07d0C77Ba9b83fcc75Fcc2a0aC243';
        const DeployAccount = promisify(client.DeployAccount.bind(client));
        const response = await DeployAccount({
          key: '02f4147da97162a214dbe25828ee4c4acc4dc721cd0c15b2761b43ed0292ed82b5',
        });
        expect(response).toHaveProperty('address', address);
      });
    });

    describe('BuildAccountTransaction', () => {
      test('generate 2 of 3 multi address', async () => {
        const address = '0x6885F32f2Cb8604f1B3D244AaC833940790aeB8D';
        const serialized =
          '';
        const signatureHash = '9a4b20f93851d49309edd428e45b221ddf6762096c8d73bc1625369db66c25d8';
        const BuildAccount = promisify(client.BuildAccountTransaction.bind(client));
        const response = await BuildAccount({
          keys: [
            '02f4147da97162a214dbe25828ee4c4acc4dc721cd0c15b2761b43ed0292ed82b5',
            '0377155e520059d3b85c6afc5c617b7eb519afadd0360f1ef03aff3f7e3f5438dd',
            '02f44bce3eecd274e7aa24ec975388d12905dfc670a99b16e1d968e6ab5f69b266',
          ],
          sender: '0xd73d9aa55abbd6cfbed3e9ad7f8be2f6d83c70dc',
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
          params: {
            nonce: 170,
            gasLimit: '0x26520c',
            gasPrice: '5000000000',
          },
        });
        expect(response).toHaveProperty('serialized', serialized);
        expect(response).toHaveProperty('address', address);
        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: signatureHash,
            }),
          ]),
        );
      });
    });

    describe('SignTransaction', () => {
      test('sign transaction', async () => {
        const serialized =
          '';
        const SignTransaction = promisify(client.SignTransaction.bind(client));
        const response = await SignTransaction({
          serialized:
            '',
          signatures: [
            {
              signature:
                '9049a72581e7723974b6e171fecf1fc70fb7843fcd02bf8443be8d82324b3de658e5e1fca4a3d7c6219c47d8aadf800f087afc7936cf31e68dff110e031584e600',
            },
          ],
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
        });
        expect(response).toHaveProperty('serialized', serialized);
      });
    });

    describe('RebuildTransaction', () => {
      test('rebuild deploy account transaction, with partial replacement', async () => {
        const serialized =
          '';
        const RebuildTransaction = promisify(client.RebuildTransaction.bind(client));
        const response = await RebuildTransaction({
          serialized:
            '',
          params: {
            gasPrice: '0x165a0bc00',
            gasLimit: '0x26820c',
          },
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
        });
        expect(response).toHaveProperty('serialized', serialized);
        expect(response.serialized).toContain('26820c');
        expect(response.serialized).toContain('165a0bc00');
      });

      test('rebuild deploy account transaction', async () => {
        const serialized =
          '';
        const RebuildTransaction = promisify(client.RebuildTransaction.bind(client));
        const response = await RebuildTransaction({
          serialized:
            '',
          params: {
            nonce: '172',
            gasPrice: '0x165a0bc00',
            gasLimit: '0x26520c',
          },
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
        });
        expect(response).toHaveProperty('serialized', serialized);
      });

      test('rebuild bnb transfer transaction with signature', async () => {
        const RebuildTransaction = promisify(client.RebuildTransaction.bind(client));
        const response = await RebuildTransaction({
          serialized:
            'f86a098502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e8008081e6a0212d53d06acb66a1bf72c75538841e7d5d52672a7204a1364467c1eb85065875a07e74ca88cab076d5e2a961ce062340f953f9a2a5d586baea844c472c14490622',
          params: {
            nonce: 10,
            gasPrice: '0x2540be400',
            gasLimit: '0xa410',
          },
          network: {
            provider: 'https://data-seed-prebsc-1-s1.binance.org:8545/',
            chainId: 97,
          },
        });

        expect(response).toHaveProperty(
          'serialized',
          'e90a8502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e80080808080',
        );
        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              pubKey: '02bd64864ea4f839d65cad1dc4576b1d52b83a48a18482ac9513dec3dae1ee9315',
              hash: 'f82536bb1134f6929e8270a0947f7536e1f1fc2974185162477067218abf6142',
            }),
          ]),
        );
      });

      test('rebuild bnb transfer transaction without signature', async () => {
        const RebuildTransaction = promisify(client.RebuildTransaction.bind(client));
        const response = await RebuildTransaction({
          serialized: 'e9098502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e80080808080',
          params: {
            nonce: 10,
            gasPrice: '0x2540be400',
            gasLimit: '0xa410',
          },
          network: {
            provider: 'https://data-seed-prebsc-1-s1.binance.org:8545/',
            chainId: 97,
          },
        });

        expect(response).toHaveProperty(
          'serialized',
          'e90a8502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e80080808080',
        );
        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: 'f82536bb1134f6929e8270a0947f7536e1f1fc2974185162477067218abf6142',
            }),
          ]),
        );
      });
    });

    describe('BuildMultisigTransactionInput', () => {
      test('build multisig transfer input', async () => {
        const BuildMultisigTransferInput = promisify(client.BuildMultisigTransferInput.bind(client));
        const response = await BuildMultisigTransferInput({
          prefix: 'ETHER',
          toAddress: '0x370BA1dc25C07d0C77Ba9b83fcc75Fcc2a0aC243',
          quantity: '100000000000000',
          data: '',
          expireTime: 1625550124,
          sequenceId: 4,
        });

        expect(response).toHaveProperty(
          'serialized',
          '',
        );

        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: '71846f6c34b07a76772e1f487a1b0b1d7ca5ad1db8ca9dae82150b0532eff88d',
            }),
          ]),
        );
      });

      test('sign multisig transfer input', async () => {
        const SignMultisigTransferInput = promisify(client.SignMultisigTransferInput.bind(client));
        const response = await SignMultisigTransferInput({
          serialized:
            '',
          signatures: [
            {
              signature:
                'd23b3dc427228e38ff91dbc724eb99e00285bf69ca0b4f6e0f77de50ba4cfcf36bb53cbea9bd83f15da1d7f14c97ce5e12c574368c20292652dc1cd8521a33631b',
              hash: '5bace34c94316df4f3330a43011eb2dc5f14fec5032105c29c3f5fc405d374a9',
            },
          ],
        });

        expect(response).toHaveProperty(
          'serialized',
          '',
        );
      });

      test('build multisig transfer transaction', async () => {
        const BuildMultisigTransferTransaction = promisify(client.BuildMultisigTransferTransaction.bind(client));
        const response = await BuildMultisigTransferTransaction({
          input:
            '',
          contract: '0x317028fb803594ebcc310481303965f984fb3e19',
          sender: '0x370BA1dc25C07d0C77Ba9b83fcc75Fcc2a0aC243',
          params: {
            nonce: 5,
            gasPrice: '0x147d35700',
            gasLimit: '0x1710e',
          },
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
        });

        expect(response).toHaveProperty(
          'serialized',
          '',
        );

        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: '11382458823f61f83fcbc4a7f974b4876197e023a717be185dffdd73db2785b8',
            }),
          ]),
        );
      });

      test('build erc20 multisig transfer input', async () => {
        const BuildMultisigTokenTransferInput = promisify(client.BuildMultisigTokenTransferInput.bind(client));
        const response = await BuildMultisigTokenTransferInput({
          tokenAddress: '0x5abe286f5ea6132b157cfd728834d493cbd43314',
          toAddress: '0x370BA1dc25C07d0C77Ba9b83fcc75Fcc2a0aC243',
          quantity: '1000000000000000000',
          expireTime: 1625569571,
          sequenceId: 7,
        });

        expect(response).toHaveProperty(
          'serialized',
          '',
        );

        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: 'df6adf08b11d59c888fbb793508e6d69de21f41c5a44b9b40ecf68597b847d5d',
            }),
          ]),
        );
      });

      test('sign only multisig transfer input', async () => {
        const SignMultisigTokenTransferInput = promisify(client.SignMultisigTokenTransferInput.bind(client));
        const response = await SignMultisigTokenTransferInput({
          serialized:
            '',
          signatures: [
            {
              signature:
                '2e1c06563f6df9c1dd20b2ee18cfbf5bba89d99ae28af590e2743b6423322f1c3e12e58bc96848663c4fe6da25ee3ab8dff377eb7151aa6f70b2e7cf9cc567051c',
              hash: 'df6adf08b11d59c888fbb793508e6d69de21f41c5a44b9b40ecf68597b847d5d',
            },
          ],
        });

        expect(response).toHaveProperty(
          'serialized',
          '',
        );
      });
    });

    describe('HashForSignature', () => {
      test('without signature', async () => {
        const HashForSignature = promisify(client.HashForSignature.bind(client));
        const response = await HashForSignature({
          serialized: 'e9098502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e80080808080',
          network: {
            provider: 'https://data-seed-prebsc-1-s1.binance.org:8545/',
            chainId: 97,
          },
        });
        expect(response).toHaveProperty(
          'serialized',
          'e9098502540be40082a410945f560610a5f64834fb2c40402226745c32ec9f8585174876e80080808080',
        );

        expect(response.signatures).toEqual(
          expect.arrayContaining([
            expect.objectContaining({
              hash: '24bc7e40046ea7d2ef8c6ab9212ac3bdc6032122f4d14518a23737a9c300579c',
            }),
          ]),
        );
      });
    });

    describe('DecodeTransaction', () => {
      test('multisig transfer transaction', async () => {
        const DecodeTransaction = promisify(client.DecodeTransaction.bind(client));
        const response = await DecodeTransaction({
          serialized:
            '',
          network: {
            provider: 'https://kovan.infura.io/v3/de9290b603fc4609a6f0a65e23e8c7d3',
            chainId: 42,
          },
        });

        expect(response).toEqual(
          expect.objectContaining({
            nonce: 5,
            gasPrice: '0x147d35700',
            gasLimit: '0x1710e',
          }),
        );
      });
    });
  });
});
